mapper.select:
SELECT ,
c.nickname AS customer_nickname,
o.shop_name AS shop_name
FROM shop_after_sale a
LEFT JOIN shop_customer c ON c.id = a.customer_id
LEFT JOIN shop_order o ON o.id = a.order_id
WHERE a.del_status = 0
AND a.shop_id = #{shopId}
AND a.after_sale_no = #{afterSaleNo}
AND a.order_no = #{orderNo}
AND a.status = #{status}
ORDER BY a.create_time DESC

SELECT COUNT(*) FROM shop_after_sale
WHERE del_status = 0 AND status = 1
AND shop_id = #{shopId}
